import styled from '@emotion/styled';

import { INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS } from './constants';

const TABLE_CELL_BORDER = '1px solid rgba(0, 0, 0, 0.16)';

export const StyledInvestmentBreakdownTableChrome = styled.div({
  width: '100%',
  border: TABLE_CELL_BORDER,
  borderRadius: '16px',
  overflow: 'hidden',
  backgroundColor: 'white',
});

export const StyledInvestmentBreakdownTableTitle = styled.div({
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  gap: '16px',
  padding: '13.5px 24px',
  borderBottom: TABLE_CELL_BORDER,
  backgroundColor: 'white',
});

export const StyledInvestmentBreakdownTableBody = styled.div({
  width: '100%',
  backgroundColor: 'rgba(0, 0, 0, 0.08)',
});

export const StyledInvestmentBreakdownTableTitleActions = styled.div({
  flexShrink: 0,
  marginLeft: 'auto',
});

export const StyledInvestmentBreakdownTableLegend = styled.div({
  display: 'flex',
  alignItems: 'center',
  height: '72px',
  padding: '0 24px',
  borderBottom: TABLE_CELL_BORDER,
  backgroundColor: 'white',

  '& [data-testid$="-indicator"], & > div > div > span:first-child': {
    width: '16px !important',
    height: '8px !important',
    minWidth: '16px',
    minHeight: '8px',
    borderRadius: '8px',
    marginBottom: '0 !important',
  },
});

export const InvestmentBreakdownTableStyles = styled.div({
  '.ag-root-wrapper': {
    border: 'none',
    backgroundColor: 'rgba(0, 0, 0, 0.08)',
  },

  '.ag-body-horizontal-scroll': {
    flexShrink: 0,
    backgroundColor: 'white',
  },

  '.ag-center-cols-viewport': {
    minHeight: 'unset',
  },

  '.ag-header': {
    backgroundColor: 'white !important',

    '.ag-header-viewport': {
      backgroundColor: 'white',
    },

    '.ag-header-row:first-child': {
      '.ag-header-cell, .ag-header-group-cell': {
        borderTop: 'none',
      },
    },

    '.ag-header-cell, .ag-header-group-cell': {
      borderTop: 'none',
      borderRight: TABLE_CELL_BORDER,
      borderBottom: TABLE_CELL_BORDER,
      borderLeft: 'none',
      backgroundColor: 'white',
      color: '#141414',
      fontWeight: 'bold',

      '&.ag-column-first:not([col-id="portfolio"])': {
        borderLeft: TABLE_CELL_BORDER,
      },

      '&[col-id="portfolio"], &.portfolio-header': {
        borderTop: 'none',
        borderLeft: 'none',
        borderRight: TABLE_CELL_BORDER,
        borderBottom: TABLE_CELL_BORDER,
      },
    },

    '.ag-header-cell': {
      color: '#1414148F',
    },

    '.ag-header-cell-subtext': {
      display: 'none',
    },

    '.portfolio-header': {
      color: 'white',
      fontWeight: 'bold',
    },

    '.brands-header': {
      color: '#141414',
      fontWeight: 'bold',

      '.ag-header-cell-text': {
        fontWeight: 'bold',
      },
    },

    '.ag-header-group-cell-label .ag-header-group-text': {
      whiteSpace: 'nowrap',
    },

    '.ag-header-row:first-child .ag-header-cell[col-id="portfolio"], .ag-header-row:first-child .ag-header-cell.portfolio-header':
      {
        borderTop: TABLE_CELL_BORDER,
      },
  },

  '.ag-row': {
    border: 'none !important',
    margin: 0,

    '.ag-cell': {
      borderTop: 'none',
      borderRight: TABLE_CELL_BORDER,
      borderBottom: TABLE_CELL_BORDER,
      borderLeft: 'none',
      zIndex: '0 !important',
      justifyContent: 'center',

      '&.ag-column-first:not([col-id="portfolio"])': {
        borderLeft: TABLE_CELL_BORDER,
      },

      '&[col-id="volume_AC"].ag-cell-first-row, &[col-id="marketing_package_FY_BU"].ag-cell-first-row, &[col-id="nwm_fy_bu"].ag-cell-first-row, &[col-id="media_fy_bu_qwoa"].ag-cell-first-row, &[col-id="sponsorship_fy_bu"].ag-cell-first-row, &[col-id="campaign_performance_fy_bu"].ag-cell-first-row':
        {
          borderLeft: TABLE_CELL_BORDER,
        },

      '.ag-cell-content': {
        justifyContent: 'center',
        alignItems: 'center',
        textAlign: 'center',
      },

      '&.ag-cell-first-row': {
        background: 'rgba(224, 243, 255, 1) !important',
        color: '#141414',
        fontWeight: 'bold',

        '.ag-cell-content': {
          whiteSpace: 'nowrap',
        },
      },

      '&[col-id="brands"]': {
        overflow: 'hidden',
        fontWeight: 'bold',

        '&.ag-cell-first-row': {
          backgroundColor: 'rgba(224, 243, 255, 1)',
          borderRight: TABLE_CELL_BORDER,
          borderBottom: TABLE_CELL_BORDER,
        },
      },

      '.ag-row-last .ag-cell.ag-column-first': {
        borderBottomLeftRadius: '16px',
      },

      '.ag-row-last .ag-cell.ag-column-last': {
        borderBottomRightRadius: '16px',
      },

      '&[col-id="portfolio"]': {
        padding: 0,
        borderTop: 'none',
        borderLeft: 'none',
        borderRight: 'none',
        borderBottom: 'none',

        '&:not(.ag-cell-first-row):not(.ag-cell-hide)': {
          maxWidth: '8px',
          minWidth: '8px',
          width: '8px',
          overflow: 'hidden',
        },

        '.ag-cell-content': {
          padding: 0,
          overflow: 'hidden',
          fontSize: 0,
          lineHeight: 0,
        },

        '&.ag-cell-megabrands:not(.ag-cell-first-row)': {
          background: `${INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.MEGABRANDS} !important`,
        },

        '&.ag-cell-expansion:not(.ag-cell-first-row)': {
          background: `${INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.EXPANSION} !important`,
        },

        '&.ag-cell-sustain:not(.ag-cell-first-row)': {
          background: `${INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.SUSTAIN} !important`,
        },

        '&.ag-cell-tail:not(.ag-cell-first-row)': {
          background: `${INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.TAIL} !important`,
        },

        '&.ag-cell-total:not(.ag-cell-first-row)': {
          background: `${INVESTMENT_BREAKDOWN_PORTFOLIO_COLORS.TOTAL} !important`,
        },

        '&.ag-cell-first-row': {
          background: 'rgba(224, 243, 255, 1) !important',
          borderRight: `${TABLE_CELL_BORDER} !important`,
          borderBottom: `${TABLE_CELL_BORDER} !important`,
          maxWidth: 'none',
          minWidth: '0',
          width: 'auto',
          overflow: 'hidden',
        },
      },
    },

    '&:nth-child(n + 2):nth-child(even) .ag-cell:not(.ag-cell-first-row):not([col-id="portfolio"])':
      {
        backgroundColor: '#f5f5f5',
      },
  },
});
